import math

class PrecisionScorer:
    def _token_vector(self, token: str) -> list[float]:
        vec = [0.0] * 26
        for c in token.lower():
            if 'a' <= c <= 'z':
                vec[ord(c) - ord('a')] += 1.0
        return vec

    def _encode(self, text: str) -> list[list[float]]:
        return [self._token_vector(w) for w in text.lower().split()]

    def _dot(self, a: list[float], b: list[float]) -> float:
        return sum(x * y for x, y in zip(a, b))

    def _norm(self, v: list[float]) -> float:
        return math.sqrt(sum(x * x for x in v))

    def _cosine(self, a: list[float], b: list[float]) -> float:
        d = self._dot(a, b)
        na, nb = self._norm(a), self._norm(b)
        if na == 0 or nb == 0:
            return 0.0
        return d / (na * nb)

    def _avg_vector(self, vectors: list[list[float]]) -> list[float]:
        if not vectors:
            return [0.0] * 26
        n = len(vectors)
        return [sum(col) / n for col in zip(*vectors)]

    def single_vector_score(self, query: str, document: str) -> float:
        q = self._encode(query)
        d = self._encode(document)
        if not q or not d:
            return 0.0
        return self._cosine(self._avg_vector(q), self._avg_vector(d))

    def maxsim_score(self, query: str, document: str) -> float:
        q = self._encode(query)
        d = self._encode(document)
        if not q or not d:
            return 0.0
        return sum(max(self._dot(qt, dt) for dt in d) for qt in q)

# Test:
scorer = PrecisionScorer()

sv1 = scorer.single_vector_score("reset password", "password reset guide")
sv2 = scorer.single_vector_score("reset password", "password policy rules")
print(f"{sv1:.4f}")
print(f"{sv2:.4f}")
print(abs(sv1 - sv2) < 0.15)

ms1 = scorer.maxsim_score("reset password", "password reset guide")
ms2 = scorer.maxsim_score("reset password", "password policy rules")
print(ms1 > ms2)

print(scorer.maxsim_score("abc", "xyz") == 0.0)

class ConstraintRetriever:
    def __init__(self):
        self.corpus = []
        self.doc_embeddings = []

    def _token_vec(self, token: str) -> list[float]:
        vec = [0.0] * 26
        for c in token.lower():
            if 'a' <= c <= 'z':
                vec[ord(c) - ord('a')] += 1.0
        return vec

    def _encode(self, text: str) -> list[list[float]]:
        return [self._token_vec(w) for w in text.lower().split()]

    def _dot(self, a: list[float], b: list[float]) -> float:
        return sum(x * y for x, y in zip(a, b))

    def _maxsim(self, q_vecs, d_vecs) -> float:
        if not q_vecs or not d_vecs:
            return 0.0
        total = 0.0
        for qv in q_vecs:
            total += max(self._dot(qv, dv) for dv in d_vecs)
        return total

    def index(self, corpus: list[str]):
        self.corpus = list(corpus)
        self.doc_embeddings = [self._encode(doc) for doc in self.corpus]

    def search(self, query: str, k: int = 3) -> list[dict]:
        q_vecs = self._encode(query)
        scored = [
            {"document": doc, "score": self._maxsim(q_vecs, emb)}
            for doc, emb in zip(self.corpus, self.doc_embeddings)
        ]
        scored.sort(key=lambda r: -r["score"])
        return scored[:k]

    def constrained_search(self, constraints: list[str], k: int = 3) -> list[dict]:
        c_vecs = [self._encode(c) for c in constraints]
        results = []
        for doc, emb in zip(self.corpus, self.doc_embeddings):
            per = [self._maxsim(cv, emb) for cv in c_vecs]
            results.append({
                "document": doc,
                "score": min(per) if per else 0.0,
                "per_constraint": per,
            })
        results.sort(key=lambda r: -r["score"])
        return results[:k]


ret = ConstraintRetriever()
ret.index([
    "async python functions with type hints",
    "python type hints for beginners",
    "async javascript promises explained",
    "python decorators and generators",
    "advanced async patterns in python code",
])

r = ret.search("async python", k=2)
print(r[0]["document"])

cr = ret.constrained_search(["async functions", "type hints"], k=2)
print(cr[0]["document"])
print(cr[0]["score"] > cr[1]["score"])

print(len(cr[0]["per_constraint"]))
